files.content:
* {
  box-sizing: border-box;
}

body {
  display: grid;
  place-items: center;
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 40px;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

h1,
h2,
p,
ul,
li {
  margin: 0;
  padding: 0;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  border: 0;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
}

.card {
  padding: 40px;
  background-color: #fff;
}

.card__title {
  margin-bottom: 40px;
  font-weight: 800;
  font-size: 31px;
  text-transform: uppercase;
}

.card__text {
  margin-bottom: 40px;
  font-weight: 800;
  font-size: 31px;
  text-transform: uppercase;
}

.card__text input {
  width: 200px;
  border: none;
  border-bottom: 2px solid currentColor;
  font-family: inherit;
  font-weight: inherit;
  font-size: inherit;
  text-transform: uppercase;
  background-color: transparent;
}

.card__text input:focus {
  outline: none;
}

.card__text input:focus-visible {
  outline: initial;
}

.card__button {
  border: 1px solid #000;
  padding: 10px 65px;
  color: #000;
  font-family: inherit;
  font-weight: 800;
  font-size: inherit;
  text-transform: uppercase;
  background-color: #ffc802;
}

.card__button:hover {
  box-shadow: inset 0 0 0 100px rgb(0 0 0 / 0.15);
  cursor: pointer;
}

.card__button:focus {
  outline: 2px solid #000;
  outline-offset: 0;
}

.overlay {
  position: fixed;
  inset: 0;
  display: none;
  background-color: rgb(0 0 0 / 0.5);
}

.answer {
  position: fixed;
  top: 0;
  right: 0;
  display: flex;
  flex-direction: column;
  width: 70%;
  height: 100%;
  padding: 20px;
  overflow-y: auto;
  background-color: #fff;
  transition: translate 1s ease-in-out;
  translate: 100%;
}

.answer_is-open {
  translate: 0;
}

.answer__header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 40px;
  font-weight: 800;
  font-size: 31px;
  text-transform: uppercase;
}

.answer__iframe {
  width: 100%;
  aspect-ratio: 16 / 9;
}

.answer__close {
  align-self: center;
  width: 50px;
  height: 50px;
  border: none;
  background-color: transparent;
  background-image: url(../svg/close.svg);
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;
  cursor: pointer;
}

.answer__close:hover {
  opacity: 0.6;
}
body:has(.answer_is-open) .overlay {
  display: block;
}
